/* NEXO / RAG LAB — Sitio educativo independiente basado en Módulo 1 · Clase 1.
   Simulaciones locales y explícitamente didácticas: no llaman a APIs ni representan
   salidas auténticas de LangChain/LlamaIndex salvo cuando se ejecuta el ejemplo Python. */
(() => {
  'use strict';
  const chapters = [
    {id:'intro',num:'00',name:'Primero, ¿qué es RAG?',sub:'El mapa completo',icon:'◎',color:'#65eaf3'},
    {id:'blind',num:'01',name:'El contexto roto',sub:'Chunking ciego',icon:'✂',color:'#ff869f'},
    {id:'recursive',num:'02',name:'Pensar en estructura',sub:'Chunking recursivo',icon:'⤷',color:'#65eaf3'},
    {id:'semantic',num:'03',name:'Entender el significado',sub:'Chunking semántico',icon:'◉',color:'#a48aff'},
    {id:'parent',num:'04',name:'Padres e hijos',sub:'Parent-Document Retrieval',icon:'⌘',color:'#fb77ce'},
    {id:'real',num:'05',name:'PDFs del mundo real',sub:'Limpiar antes de buscar',icon:'▤',color:'#eeca84'},
    {id:'choose',num:'06',name:'Elegir una estrategia',sub:'Comparar y decidir',icon:'◇',color:'#8ce2bc'},
    {id:'exam',num:'07',name:'Desafío final',sub:'Comprobá lo aprendido',icon:'✧',color:'#fb77ce'},
  ];
  const byId = Object.fromEntries(chapters.map(c => [c.id,c]));
  const main = document.getElementById('main');
  const nav = document.getElementById('lesson-nav');
  const storageKey = 'nexo-rag-lab-2026-v1';
  function safeStorageRead(){try{return JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{return {}}}
  const saved = safeStorageRead();
  const state = {
    current:'overview',done:new Set((saved.done||[]).filter(x=>byId[x])),best:Number(saved.best||0),
    fixedSize:110,recSize:160,recOverlap:25,semThreshold:45,
    text:'El sistema debe responder en español. ¿Cómo se configura el idioma? Se utiliza el parámetro language en la configuración. Esta instrucción debe conservarse junto a su respuesta.',
    recText:'## Política de devoluciones\n\nLas devoluciones se aceptan dentro de los 30 días de realizada la compra. Es obligatorio presentar el comprobante de pago.\n\n## Productos excluidos\n\nLos artículos personalizados no admiten devolución, salvo que presenten fallas de fabricación.\n\n## Contacto\n\nPara solicitar ayuda, escribí a soporte. El equipo responderá dentro de las 48 horas hábiles.',
    retrieval:'contract',scenario:'manual',quizIndex:0,quizPick:null,quizRevealed:false,quizScore:0,story:'meaning'
  };
  function persist(){try{localStorage.setItem(storageKey,JSON.stringify({done:[...state.done],best:state.best}))}catch{}}
  function esc(str){return String(str).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
  function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3200)}
  function refreshNav(){
    const count=state.done.size,percent=Math.round(100*count/chapters.length);
    document.getElementById('progress-percent').textContent=`${percent}%`;
    document.getElementById('progress-fill').style.width=`${percent}%`;
    document.getElementById('progress-note').textContent=count===chapters.length?'¡Ruta completa!':`${count} de ${chapters.length} etapas completadas`;
    nav.innerHTML = `<button class="lesson-btn ${state.current==='overview'?'active':''}" data-go="overview"><span class="lesson-number">⌂</span><span class="lesson-name">Panel principal<small>Empezá por acá</small></span></button>`+chapters.map(c=>`<button class="lesson-btn ${state.current===c.id?'active':''} ${state.done.has(c.id)?'done':''}" data-go="${c.id}" ${state.current===c.id?'aria-current="page"':''}><span class="lesson-number">${state.done.has(c.id)?'✓':c.num}</span><span class="lesson-name">${c.name}<small>${c.sub}</small></span></button>`).join('');
  }
  function go(id){if(id!=='overview'&&id!=='studio'&&!byId[id])return;state.current=id;refreshNav();render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}
  function complete(id){if(byId[id]){state.done.add(id);persist();refreshNav();toast('✓ Etapa guardada en tu progreso.')}}
  function nextOf(id){const index=chapters.findIndex(c=>c.id===id);return chapters[index+1]?.id||'studio'}
  function lessonFrame(id,title,subtitle,core,body){const c=byId[id];const done=state.done.has(id);return `<div class="page lesson-page"><div class="lesson-head"><div class="lesson-topline"><span class="pill">MÓDULO 01 · CLASE 01</span><span class="lesson-count">UNIDAD ${c.num} / 07</span></div><h1>${title}</h1><p class="lead">${subtitle}</p></div><div class="lesson-summary"><span class="summary-icon">✦</span><div><b>Idea para llevarte:</b> ${core}</div></div>${body}<div class="lesson-bottom"><div class="lesson-bottom-text"><strong>${done?'✓ Esta etapa ya está completada':'¿Te quedó clara la idea central?'}</strong>Tu progreso se guarda en este navegador.</div><div class="lesson-bottom-actions"><button class="button button-muted" data-complete="${id}">${done?'✓ Repasar completado':'✓ Marcar como aprendido'}</button><button class="button" data-go="${nextOf(id)}">Siguiente etapa →</button></div></div></div>`}
  function sectionTitle(index,title,tail=''){return `<div class="section-heading"><div><span class="section-index">${index}</span><h2>${title}</h2></div>${tail?`<small>${tail}</small>`:''}</div>`}
  function codeBlock(id,label,code){window.__nexoCode=window.__nexoCode||{};window.__nexoCode[id]=code;return `<div class="codebox"><div class="codebar"><span><span class="code-dots">● ● ●</span> &nbsp; ${esc(label)}</span><button class="code-copy" data-copy="${id}">Copiar código</button></div><pre><code>${esc(code)}</code></pre></div>`}
  const codeRecursive=`from langchain_text_splitters import RecursiveCharacterTextSplitter\n\nsplitter = RecursiveCharacterTextSplitter(\n    chunk_size=500,\n    chunk_overlap=50,\n    separators=["\\n\\n", "\\n", " ", ""]\n)\n\nchunks = splitter.split_text(documento)\nprint(f"Fragmentos: {len(chunks)}")`;
  const codeLlama=`from llama_index.core.node_parser import SentenceSplitter\n\nsplitter = SentenceSplitter(\n    chunk_size=120,       # tokens, no caracteres\n    chunk_overlap=20\n)\nchunks = splitter.split_text(documento)`;
  function overview(){
    return `<div class="page overview-page"><div class="hero"><div class="hero-copy"><span class="overline">APRENDER IA · SIN HUMO</span><h1>Dividí el texto.<br><span class="glow-text">No el sentido.</span></h1><p class="lead">Una clase entera convertida en un laboratorio visual. Aprendé desde cero cómo se preparan los documentos para construir sistemas de IA que recuperan información confiable.</p><div class="hero-actions"><button class="button" data-go="intro">Empezar a explorar ↗</button><button class="button button-outline" data-go="blind">Probar laboratorio ✂</button></div><div class="micro-info"><span><b>07</b> temas guiados</span><span><b>04</b> experiencias prácticas</span><span><b>08</b> preguntas finales</span><span><b>01</b> generador de historias</span></div></div><div class="hero-graphic" aria-hidden="true"><div class="orbit"></div><div class="orbit orb2"></div><div class="orbit orb3"></div><div class="orbit-node n1"><span class="node-icon">▤</span><b>DOCUMENTO</b><span>entrada</span></div><div class="orbit-node n2"><span class="node-icon">✂</span><b>CHUNKS</b><span>segmentación</span></div><div class="orbit-node n3"><span class="node-icon">⌁</span><b>RETRIEVAL</b><span>búsqueda</span></div><div class="orbit-node n4"><span class="node-icon">✧</span><b>RESPUESTA</b><span>contexto</span></div><div class="central-node"><div><span>NEXO / LAB</span><strong>RAG</strong><small>01. SEGMENTACIÓN</small></div></div></div></div><div class="notice-strip"><strong>◎</strong><div><b>¿Primera vez que escuchás “chunking”?</b> Perfecto. No necesitás conocimientos previos ni claves de IA. Todos los laboratorios web funcionan en tu navegador. Vas a ver, tocar y romper ejemplos para comprenderlos.</div></div>${sectionTitle('EXPLORÁ EL CONTENIDO','Elegí tu próxima misión','RUTA DE APRENDIZAJE')}<div class="course-grid">${chapters.slice(0,7).map(c=>`<button class="course-card" data-go="${c.id}" style="--accent:${c.color}"><div class="course-top"><span class="course-code">CAPÍTULO / ${c.num}</span><span class="course-glyph">${c.icon}</span></div><h3>${c.name}</h3><p>${getCardDescription(c.id)}</p>${state.done.has(c.id)?'<span class="course-status">✓ COMPLETADO</span>':''}</button>`).join('')}<button class="course-card" data-go="exam" style="--accent:#fb77ce"><div class="course-top"><span class="course-code">BONUS / 07</span><span class="course-glyph">✧</span></div><h3>Desafío final</h3><p>Ocho preguntas, decisiones de ingeniería y feedback inmediato.</p>${state.done.has('exam')?'<span class="course-status">✓ COMPLETADO</span>':''}</button><button class="course-card" data-go="studio" style="--accent:#a48aff"><div class="course-top"><span class="course-code">SOCIAL / IG</span><span class="course-glyph">↗</span></div><h3>Story Studio</h3><p>Convertí lo aprendido en una historia vertical 9:16 para compartir.</p></button></div><div class="panel highlight full"><span class="kicker">EL OBJETIVO REAL DE ESTA CLASE</span><p class="callout-quote">“Un sistema RAG no empieza en la base de datos, sino en cómo preparamos y entendemos la estructura de los documentos.”</p><p>Basado en el enfoque de <b>Clase 1: Estrategias de Segmentación Avanzada</b>. La experiencia reorganiza los conceptos para quienes están empezando. No es un sitio oficial del curso.</p><span class="source-chip">Material de clase, página 6</span></div></div>`;
  }
  function getCardDescription(id){return ({intro:'Entendé el viaje de una pregunta desde el documento hasta una respuesta.',blind:'Mirá qué sucede cuando una máquina corta sin comprender.',recursive:'Descubrí cómo respetar párrafos, saltos y palabras.',semantic:'Separá donde cambia el tema, no solo por longitud.',parent:'Buscá en fragmentos pequeños; recuperá el contexto grande.',real:'Tablas, columnas y ruido: el caos previo al chunking.',choose:'Compará técnicas y decidí cuál aplicar en cada escenario.'})[id]}
  function intro(){return lessonFrame('intro','Antes de cortar: <span class="glow-text">entendé el mapa.</span>','Empecemos desde cero. ¿Qué hace un sistema RAG y dónde entra la segmentación?','RAG busca información relevante en una fuente externa y se la entrega al modelo como contexto para responder.',
    `${sectionTitle('01 / LA IDEA','¿Qué es RAG?')}<div class="content-grid"><div class="panel"><span class="big-icon">▤</span><h3>Una IA con material de consulta</h3><p>Imaginate una IA que tiene que responder sobre un manual técnico. En vez de depender solamente de lo aprendido durante su entrenamiento, primero <strong class="text-accent">busca información en ese manual</strong>.</p></div><div class="panel pink"><span class="big-icon">◈</span><h3>RAG = buscar y luego responder</h3><p><strong>Retrieval-Augmented Generation</strong> significa “generación aumentada con recuperación”. Se recuperan pasajes relevantes, y luego un modelo de lenguaje genera una respuesta utilizando ese contexto.</p></div></div>${sectionTitle('02 / FLUJO','Seguí el camino de la información')}<div class="flow-strip"><div class="flow-step"><span class="flow-symbol">▤</span>Fuente<strong>Documento</strong></div><span class="flow-arrow">→</span><div class="flow-step active"><span class="flow-symbol">✂</span>Preparar<strong>Chunks</strong></div><span class="flow-arrow">→</span><div class="flow-step"><span class="flow-symbol">⌁</span>Indexar<strong>Embeddings</strong></div><span class="flow-arrow">→</span><div class="flow-step"><span class="flow-symbol">◎</span>Consultar<strong>Recuperación</strong></div><span class="flow-arrow">→</span><div class="flow-step"><span class="flow-symbol">✧</span>Generar<strong>Respuesta</strong></div></div><div class="panel note"><span class="kicker">PREGUNTA IMPORTANTE</span><h3>¿Por qué no pasar siempre el documento entero?</h3><p>Puede ser largo, costoso o contener información irrelevante para la pregunta. Por eso se preparan e indexan fragmentos para recuperar solo lo necesario. <b>Pero si esos fragmentos se construyen mal, se pierde significado.</b></p></div>${sectionTitle('03 / DICCIONARIO','Cinco palabras que vas a escuchar')}<div class="content-grid"><div class="panel"><h3><span class="text-accent">Chunk</span></h3><p>Fragmento de un documento que usamos como unidad de procesamiento o búsqueda.</p></div><div class="panel"><h3><span class="text-pink">Retriever</span></h3><p>Componente que encuentra información relevante para una consulta.</p></div><div class="panel"><h3><span class="text-accent">Embedding</span></h3><p>Representación numérica que permite comparar similitudes de significado.</p></div><div class="panel"><h3><span class="text-pink">LLM</span></h3><p>Modelo de lenguaje capaz de generar texto a partir de las instrucciones y el contexto recibido.</p></div></div><div class="panel full"><h3>¿Y LangChain y LlamaIndex?</h3><p>Son frameworks que permiten organizar componentes de aplicaciones basadas en IA. En esta clase usamos sus herramientas de segmentación. <strong>Importante:</strong> un splitter no “comprende” automáticamente el contenido por utilizar un framework: el resultado depende de su estrategia, parámetros y datos de entrada.</p><span class="source-chip">Páginas 6, 8, 10 y 31</span></div>`)}
  function blind(){return lessonFrame('blind','El problema del <span class="glow-text">contexto roto.</span>','Una máquina puede encontrar las palabras correctas y, aun así, recibir la información equivocada.','Cortar “cada N caracteres” ignora frases, tablas y relaciones importantes. Un fragmento incompleto puede producir respuestas engañosas.',
    `${sectionTitle('01 / ENTENDÉ','Una respuesta cortada cambia la historia')}<div class="panel warning full"><span class="kicker text-pink">EJEMPLO DE UNA CONDICIÓN</span><p class="callout-quote">“La devolución se permite en 30 días, <span class="text-pink">siempre que se presente el comprobante.</span>”</p><p>Si la IA recupera solo el comienzo, podría decir “se permite la devolución en 30 días” e ignorar la condición. Esa respuesta parece válida, pero omite información esencial.</p></div>${sectionTitle('02 / EXPERIMENTO','Jugá con una tijera ciega','LABORATORIO 01')}<div class="lab"><div class="lab-head"><div><span class="kicker">LAB / SIMULACIÓN LOCAL</span><h3>Segmentación por tamaño fijo</h3><p>Mové el control para ver dónde se corta el texto, sin respetar palabras ni ideas.</p></div><span class="lab-tag">LIVE / JS</span></div><div class="lab-body"><div class="lab-grid"><div><label class="field-label" for="fixed-size">Tamaño del chunk <output id="fixed-out">${state.fixedSize} caracteres</output></label><div class="range-field"><input id="fixed-size" type="range" min="30" max="190" step="10" value="${state.fixedSize}"><div class="range-ends"><span>30</span><span>190</span></div></div><label class="field-label" for="fixed-text">Documento de prueba</label><textarea id="fixed-text" class="text-source" spellcheck="false">${esc(state.text)}</textarea></div><div><span class="field-label">Resultado de la segmentación</span><div class="lab-meta" id="fixed-meta"></div><div class="split-result" id="fixed-result" aria-live="polite"></div></div></div><div class="lab-note">Fijate si un fragmento queda con la pregunta y otro con la respuesta. Este laboratorio corta de forma literal: <b>no está ejecutando LangChain</b>.</div></div></div><div class="content-grid"><div class="panel warning"><h3>1. Recuperación incompleta</h3><p>El buscador encuentra un chunk con palabras muy parecidas a la consulta, pero sin el dato completo.</p></div><div class="panel"><h3>2. Respuesta sin base suficiente</h3><p>El LLM puede completar los huecos con una respuesta plausible y errónea. Esto es un riesgo de alucinación, no una consecuencia inevitable.</p></div></div><div class="panel note full"><p class="callout-quote">La segmentación no es un ajuste cosmético. Es una decisión de arquitectura.</p><span class="source-chip">Páginas 9 y 10</span></div>`)}
  function recursive(){return lessonFrame('recursive','No cortes a ciegas. <span class="glow-text">Respetá la forma.</span>','La alternativa práctica: darle prioridad a la estructura natural del documento.','RecursiveCharacterTextSplitter intenta dividir primero por separadores de mayor jerarquía; solo baja a otros niveles cuando hace falta.',
    `${sectionTitle('01 / CONCEPTO','Una escalera de separadores')}<div class="content-grid"><div class="panel"><div class="explain-row"><span class="step-circle">01</span><div><b>Párrafos</b><p>Primero intenta separar donde hay dobles saltos de línea.</p></div></div><div class="explain-row"><span class="step-circle">02</span><div><b>Saltos de línea</b><p>Si un bloque es demasiado largo, prueba saltos simples.</p></div></div><div class="explain-row"><span class="step-circle">03</span><div><b>Espacios</b><p>Si todavía excede el límite, intenta separar por palabras.</p></div></div><div class="explain-row"><span class="step-circle">04</span><div><b>Caracteres</b><p>Último recurso: puede cortar dentro de una palabra.</p></div></div></div><div class="panel pink"><span class="big-icon">⌁</span><h3>El solapamiento: <i>overlap</i></h3><p>Es una porción de contenido compartida entre chunks consecutivos. Ayuda a conservar pistas que quedaron en un borde.</p><p><b>Pero ojo:</b> demasiado overlap duplica datos y puede aumentar el costo de indexación y recuperación. No siempre es mejor.</p><div class="divider"></div><div class="key-terms"><span class="term-pill"><b>chunk_size</b> límite de tamaño</span><span class="term-pill"><b>chunk_overlap</b> repetición</span><span class="term-pill"><b>separators</b> prioridad</span><span class="term-pill"><b>length_function</b> medida</span></div></div></div>${sectionTitle('02 / EXPERIMENTO','Cortá sin destruir la estructura','LABORATORIO 02')}<div class="lab"><div class="lab-head"><div><span class="kicker">LAB / APROXIMACIÓN EDUCATIVA</span><h3>Simulador de chunking recursivo</h3><p>Escribí tus propios párrafos y ajustá tamaño y overlap.</p></div><span class="lab-tag">LIVE / JS</span></div><div class="lab-body"><div class="lab-grid"><div><label class="field-label" for="recursive-size">chunk_size <output id="recursive-out">${state.recSize} caracteres</output></label><div class="range-field"><input id="recursive-size" type="range" min="70" max="350" step="10" value="${state.recSize}"><div class="range-ends"><span>70</span><span>350</span></div></div><label class="field-label" for="overlap-size">chunk_overlap <output id="overlap-out">${state.recOverlap} caracteres</output></label><div class="range-field"><input id="overlap-size" type="range" min="0" max="80" step="5" value="${state.recOverlap}"><div class="range-ends"><span>0</span><span>80</span></div></div><label class="field-label" for="recursive-text">Documento de prueba</label><textarea id="recursive-text" class="text-source">${esc(state.recText)}</textarea></div><div><span class="field-label">Chunks resultantes</span><div id="recursive-meta" class="lab-meta"></div><div id="recursive-result" class="split-result" aria-live="polite"></div></div></div><div class="lab-note">Este simulador está inspirado en la jerarquía de LangChain, pero <b>no reproduce exactamente</b> todos los detalles de su algoritmo. Para comprobar la implementación real, ejecutá el código Python de abajo.</div></div></div>${sectionTitle('03 / PYTHON','El código que sí podés ejecutar','LANGCHAIN')}${codeBlock('recursive','ejemplo_langchain.py',codeRecursive)}<div class="panel full"><h3>Un detalle de ingeniería importante</h3><p>En el ejemplo, <code>chunk_size</code> se mide en caracteres porque se utiliza la función de longitud predeterminada <code>len</code>. Los modelos de IA suelen manejar límites en <b>tokens</b>; podemos incorporar un tokenizer si necesitamos esa unidad. El overlap pedido es un objetivo y su resultado exacto depende de cómo se formen los fragmentos.</p><p>También podés usar LlamaIndex para dividir textos por oraciones y medir los chunks en tokens.</p>${codeBlock('llama','ejemplo_llamaindex.py',codeLlama)}<span class="source-chip">Páginas 12 a 15</span></div>`)}
  const semanticSentences = [
    'El inventario muestra faltantes en tres sucursales.',
    'La reposición busca equilibrar el stock disponible.',
    'Los productos rotan a distintas velocidades.',
    'Los embeddings convierten textos en representaciones numéricas.',
    'La similitud coseno compara la dirección de dos vectores.',
    'Los buscadores pueden recuperar información por similitud.',
    'Un sintetizador produce sonidos electrónicos.',
    'La música techno organiza capas rítmicas y texturas.'
  ];
  const demoSimilarities = [.89,.84,.16,.91,.83,.19,.88];
  function semantic(){return lessonFrame('semantic','Cortá cuando <span class="glow-text">cambia la idea.</span>','El chunking semántico pregunta “¿estas oraciones hablan de lo mismo?” en lugar de fijarse solo en su longitud.','Los embeddings permiten representar significado. Una caída en la similitud entre oraciones cercanas puede señalar un cambio de tema.',
    `${sectionTitle('01 / CONCEPTO','De palabras a significado')}<div class="content-grid"><div class="panel"><div class="explain-row"><span class="step-circle">01</span><div><b>Separar en oraciones</b><p>El documento se divide en unidades más pequeñas.</p></div></div><div class="explain-row"><span class="step-circle">02</span><div><b>Generar embeddings</b><p>Cada oración se transforma en un vector numérico.</p></div></div><div class="explain-row"><span class="step-circle">03</span><div><b>Comparar similitudes</b><p>La similitud coseno ayuda a detectar afinidad entre vectores vecinos.</p></div></div><div class="explain-row"><span class="step-circle">04</span><div><b>Detectar cambios de tema</b><p>Las discontinuidades semánticas pueden indicar nuevos chunks.</p></div></div></div><div class="panel violet"><span class="big-icon">◉</span><h3>No es magia: hay cálculo</h3><p>Un <b>embedding</b> es una representación en números del contenido. Si dos textos tratan temas parecidos, sus vectores pueden ubicarse cerca en el espacio de representación.</p><p>La <b>similitud coseno</b> compara su dirección. No mide verdad, ni comprensión perfecta, ni garantiza que dos textos equivalgan.</p><span class="pill pink">SIMILITUD ≠ VERDAD</span></div></div>${sectionTitle('02 / EXPERIMENTO','Encontrá los cambios de tema','LABORATORIO 03')}<div class="lab"><div class="lab-head"><div><span class="kicker">LAB / DATOS DE DEMOSTRACIÓN</span><h3>Radar de similitud semántica</h3><p>Mové el umbral: las conexiones con menor similitud se cortan y se crean grupos temáticos.</p></div><span class="lab-tag">LIVE / DEMO</span></div><div class="lab-body"><label class="field-label" for="semantic-threshold">Umbral ilustrativo de similitud <output id="semantic-out">0.${state.semThreshold}</output></label><div class="range-field"><input type="range" id="semantic-threshold" min="10" max="95" step="5" value="${state.semThreshold}"><div class="range-ends"><span>0.10 · más grupos grandes</span><span>0.95 · más cortes</span></div></div><div class="lab-grid"><div><span class="field-label">Oraciones y afinidad con la siguiente</span><div id="similarity-list" class="similarity-list"></div></div><div><span class="field-label">Grupos resultantes</span><div id="semantic-meta" class="lab-meta"></div><div id="semantic-groups"></div></div></div><div class="lab-note"><b>Importante:</b> los valores de similitud de este simulador están <b>predefinidos para enseñar el mecanismo</b>. No calculamos embeddings reales. El parámetro <code>breakpoint_percentile_threshold</code> de LlamaIndex es un <b>percentil de distancias</b>, no este control numérico directo de similitud; no deben confundirse.</div></div></div><div class="content-grid"><div class="panel"><h3>Ventaja</h3><p>Conservar temas más coherentes puede mejorar algunas búsquedas, especialmente en textos donde el sentido cambia mucho entre secciones.</p></div><div class="panel pink"><h3>Costo</h3><p>Necesitás generar embeddings para detectar cambios de tema. Eso requiere más procesamiento que cortar solo por caracteres.</p></div></div><div class="panel note full"><h3>Herramienta presentada en la clase</h3><p><code>SemanticSplitterNodeParser</code> de LlamaIndex permite segmentación semántica con un modelo de embeddings. El material muestra un ejemplo usando <code>OpenAIEmbedding</code>: para ejecutarlo necesitarías instalar el paquete correspondiente y configurar una API. Este sitio <b>no solicita claves</b> ni consume API.</p><span class="source-chip">Páginas 16 a 18</span></div>`)}
  const parentDocs={
    contract:{label:'Contrato',question:'¿Cuándo puedo cancelar?',short:'Cancelación con 30 días de preaviso.',full:'CLÁUSULA 12 · RESCISIÓN. El contrato podrá cancelarse con un preaviso de 30 días, siempre que las partes no mantengan obligaciones pendientes. La solicitud se enviará por escrito al domicilio contractual.',reason:'La condición sobre obligaciones pendientes aparece en el padre, aunque el fragmento hijo sea más corto.'},
    manual:{label:'Manual técnico',question:'¿Cómo se configura el idioma?',short:'Configuración: language="es".',full:'SECCIÓN 4 · IDIOMA. Para configurar el idioma predeterminado, el sistema debe incluir language="es" en su configuración. Después es necesario reiniciar el servicio para aplicar el cambio.',reason:'El fragmento hijo identifica el parámetro; el padre agrega el paso de reiniciar.'},
    shipping:{label:'Política comercial',question:'¿En cuánto tiempo llega mi pedido?',short:'Envío: plazo estimado de 48 horas.',full:'ENVÍOS · Los pedidos dentro del área metropolitana se entregan normalmente en 48 horas hábiles desde la confirmación del pago. El plazo puede variar durante feriados o contingencias logísticas.',reason:'El padre aclara que son horas hábiles y aporta las excepciones.'}
  };
  function parent(){return lessonFrame('parent','Encontrá lo pequeño. <span class="glow-text">Recuperá lo grande.</span>','Un truco poderoso para solucionar el dilema entre precisión de búsqueda y contexto suficiente.','Parent-Document Retrieval indexa fragmentos hijos pequeños y, cuando encuentra uno relevante, recupera el documento o bloque padre asociado.',
    `${sectionTitle('01 / EL DILEMA','¿Pequeño o grande? Mejor: ambos.')}<div class="content-grid"><div class="panel"><span class="big-icon">✦</span><h3>Chunk hijo · pequeño</h3><p>Sirve para encontrar coincidencias específicas. En general, puede aumentar la precisión de la búsqueda al concentrarse en un dato puntual.</p><span class="pill pink">SE INDEXA PARA BUSCAR</span></div><div class="panel pink"><span class="big-icon">▣</span><h3>Documento padre · grande</h3><p>Entrega al modelo el contexto amplio: detalles, pasos, condiciones y excepciones que rodean a ese dato.</p><span class="pill">SE RECUPERA PARA CONTEXTO</span></div></div>${sectionTitle('02 / EXPERIMENTO','Elegí una pregunta','LABORATORIO 04')}<div class="lab"><div class="lab-head"><div><span class="kicker">LAB / VÍNCULO PADRE-HIJO</span><h3>Búsqueda pequeña, respuesta completa</h3><p>El sistema encuentra un hijo relevante y sigue su vínculo hacia el bloque padre.</p></div><span class="lab-tag">LIVE / DEMO</span></div><div class="lab-body"><span class="field-label">Probá uno de estos documentos</span><div class="choice-grid">${Object.entries(parentDocs).map(([id,v])=>`<button data-retrieval="${id}" class="choice-card ${state.retrieval===id?'selected':''}"><b>${esc(v.label)}</b><small>${esc(v.question)}</small></button>`).join('')}</div><div class="retrieval-display" id="retrieval-result"></div><div id="retrieval-reason" class="lab-note"></div><div class="lab-note">Este ejemplo usa casos predeterminados para explicar la relación hijo → padre. <b>No ejecuta una base vectorial ni un retriever real.</b></div></div></div>${sectionTitle('03 / ARQUITECTURA','Qué pasa por debajo')}<div class="flow-strip"><div class="flow-step"><span class="flow-symbol">▤</span>Entrada<strong>Padre largo</strong></div><span class="flow-arrow">→</span><div class="flow-step active"><span class="flow-symbol">✂</span>Indexado<strong>Hijos cortos</strong></div><span class="flow-arrow">→</span><div class="flow-step"><span class="flow-symbol">⌁</span>Búsqueda<strong>Match hijo</strong></div><span class="flow-arrow">→</span><div class="flow-step active"><span class="flow-symbol">▣</span>Resultado<strong>Padre completo</strong></div></div><div class="panel full"><h3>¿Cuándo sirve?</h3><p>En manuales técnicos, contratos extensos, preguntas frecuentes o bases de conocimiento empresariales. La recuperación del padre <b>puede</b> ayudar a preservar excepciones y condiciones, aunque no garantiza por sí sola respuestas correctas: también hay que evaluar la búsqueda y el modelo.</p><span class="source-chip">Páginas 20 a 23</span></div>`)}
  function real(){return lessonFrame('real','Antes de segmentar, <span class="glow-text">limpiá el caos.</span>','Un PDF puede verse perfecto para una persona y convertirse en texto desordenado al extraerlo.','El splitter no puede reparar por sí solo una extracción defectuosa. Primero preservamos estructura, limpiamos ruido y añadimos metadatos.',
    `${sectionTitle('01 / PROBLEMAS REALES','Los enemigos de una buena búsqueda')}<div class="content-grid"><div class="panel warning"><span class="big-icon">▦</span><h3>Tablas rotas</h3><p>Un extractor puede mezclar celdas y separar encabezados de valores. El modelo pierde la relación entre columnas.</p></div><div class="panel pink"><span class="big-icon">▥</span><h3>Doble columna</h3><p>Puede leer alternadamente la izquierda y la derecha, creando frases que nunca existieron.</p></div><div class="panel"><span class="big-icon">☷</span><h3>Encabezados repetidos</h3><p>Títulos, números de página y pies se repiten en cada chunk y generan ruido.</p></div><div class="panel violet"><span class="big-icon">☰</span><h3>Listas separadas</h3><p>Una viñeta puede perder el título o la condición a la que pertenecía.</p></div></div>${sectionTitle('02 / DEMO','Del texto sucio a uno útil','PRUEBA VISUAL')}<div class="lab"><div class="lab-head"><div><span class="kicker">LAB / PREPROCESAMIENTO</span><h3>Activá el pipeline de limpieza</h3><p>Compará una extracción desordenada con un texto estructurado y enriquecido.</p></div><span class="lab-tag">DEMO / ANTES-DESPUÉS</span></div><div class="lab-body"><div class="story-actionrow"><button class="button button-muted" data-clean="raw" id="clean-raw">01 · Texto crudo</button><button class="button button-outline" data-clean="clean" id="clean-good">02 · Texto preparado</button></div><div class="panel full" id="clean-output" aria-live="polite"></div><div class="lab-note">La transformación de ejemplo está preparada manualmente para enseñar el criterio. En producción, la extracción y detección de estructura requieren herramientas específicas y validación del resultado.</div></div></div>${sectionTitle('03 / PIPELINE','Las cuatro operaciones clave')}<div class="content-grid"><div class="panel"><div class="kicker">01 · EXTRACCIÓN</div><h3>Preservar estructura</h3><p>Usar herramientas como PyMuPDF, pdfplumber o Unstructured para identificar secciones y tablas.</p></div><div class="panel"><div class="kicker">02 · LIMPIEZA</div><h3>Eliminar ruido</h3><p>Quitar cabeceras o pies repetidos y caracteres inútiles, sin borrar información necesaria.</p></div><div class="panel"><div class="kicker">03 · NORMALIZACIÓN</div><h3>Ordenar el contenido</h3><p>Unificar codificación y espacios, revisar saltos de línea artificiales y conservar la organización real.</p></div><div class="panel"><div class="kicker">04 · METADATOS</div><h3>Guardar procedencia</h3><p>Adjuntar <code>source</code>, <code>page_number</code> y <code>section_title</code> para filtrar y citar las fuentes.</p></div></div><div class="panel note full"><h3>¿Por qué importa tanto?</h3><p>La clase enfatiza que el preprocesamiento es decisivo para la calidad final del sistema. Su frase “80% del éxito” es un recurso pedagógico, <b>no una proporción universal comprobada</b>. La lección práctica es clara: ningún splitter arregla automáticamente datos mal extraídos.</p><span class="source-chip">Páginas 24 a 28</span></div>`)}
  const scenarios={
    manual:{icon:'▤',title:'Manual con procedimientos',summary:'Un manual largo contiene preguntas concretas y respuestas dispersas en secciones completas.',method:'Parent-Document Retrieval',why:'Buscás en hijos pequeños y recuperás el bloque padre para conservar los pasos y condiciones del procedimiento.',warning:'Primero verificá títulos, secciones y calidad de la extracción.'},
    prose:{icon:'✦',title:'Artículo técnico denso',summary:'El documento cambia de tema sin señales visuales claras.',method:'Chunking semántico',why:'Los embeddings pueden ayudar a detectar cambios temáticos y formar grupos más coherentes.',warning:'Tiene costo de procesamiento; compará contra un splitter recursivo como baseline.'},
    markdown:{icon:'⌘',title:'Guía en Markdown',summary:'El texto está bien organizado con encabezados y párrafos.',method:'Chunking recursivo',why:'Los separadores jerárquicos se ajustan a una estructura que ya existe.',warning:'Podés agregar separadores propios del formato, como encabezados Markdown.'},
    prototype:{icon:'✂',title:'Prototipo de prueba',summary:'Tenés texto simple y necesitás una primera referencia rápida.',method:'Fixed-size splitting',why:'Es barato y simple para establecer una línea base inicial.',warning:'No lo des por suficiente: evaluá si los cortes pierden condiciones y respuestas.'}
  };
  function choose(){return lessonFrame('choose','No existe el splitter <span class="glow-text">perfecto.</span>','El trabajo de ingeniería empieza cuando comparás alternativas con criterio.','La mejor estrategia depende de la estructura, la precisión que necesitás, el costo y las preguntas que deben responderse.',
    `${sectionTitle('01 / COMPARATIVA','Las cuatro técnicas de la clase')}<div class="decision-table"><div class="decision-row header"><span>TÉCNICA</span><span>CASO TÍPICO</span><span>DIFICULTAD</span><span>COSTO</span></div><div class="decision-row"><strong>Fixed-size</strong><span>Prototipos, texto simple</span><span>Baja</span><em>Mínimo</em></div><div class="decision-row"><strong>Recursivo</strong><span>Markdown, código, prosa</span><span>Media</span><em>Bajo</em></div><div class="decision-row"><strong>Semántico</strong><span>Artículos técnicos densos</span><span>Alta</span><em>Medio</em></div><div class="decision-row"><strong>Padre / Hijo</strong><span>Manuales, FAQs, contratos</span><span>Alta</span><em>Medio-alto</em></div></div><p class="source-chip">Resumen cualitativo basado en la página 29: los costos reales dependen de la implementación.</p>${sectionTitle('02 / DECISIONES','¿Cuál usarías vos?','CONSULTOR DE ESTRATEGIA')}<div class="lab"><div class="lab-head"><div><span class="kicker">LAB / CASOS DE USO</span><h3>Elegí el tipo de documento</h3><p>El explorador te devuelve una estrategia inicial y sus advertencias.</p></div><span class="lab-tag">DECISION / DEMO</span></div><div class="lab-body"><div class="case-grid">${Object.entries(scenarios).map(([id,v])=>`<button data-scenario="${id}" class="case-button ${state.scenario===id?'selected':''}"><span>${v.icon}</span><b>${esc(v.title)}</b><small>${esc(v.summary)}</small></button>`).join('')}</div><div class="panel highlight full" id="scenario-result"></div><div class="lab-note">Estas son hipótesis iniciales, <b>no reglas absolutas</b>. En un proyecto real comparás precisión de recuperación, cobertura de respuestas, latencia, costo y casos de error.</div></div></div>${sectionTitle('03 / SALIDA','Tu checklist de ingeniería')}<div class="content-grid"><div class="panel"><h3>Antes de segmentar</h3><ul><li>¿Qué tipo de documento tengo?</li><li>¿La extracción conserva las tablas?</li><li>¿Qué preguntas responderá el usuario?</li><li>¿Tengo metadatos y una referencia de origen?</li></ul></div><div class="panel pink"><h3>Después de segmentar</h3><ul><li>¿Las condiciones quedaron juntas?</li><li>¿Los fragmentos son coherentes?</li><li>¿El sistema recupera la evidencia correcta?</li><li>¿Puedo comparar contra otra estrategia?</li></ul></div></div><div class="panel note full"><h3>Conexión con la Clase 2</h3><p>Hasta ahora preparamos fragmentos. El siguiente paso del programa es convertirlos en <b>embeddings</b> e indexarlos en sistemas de búsqueda vectorial. En la clase se mencionan Pinecone, Weaviate, Milvus y Supabase, así como HNSW e IVF como técnicas de indexación.</p><span class="source-chip">Páginas 29 a 32</span></div>`)}
  const quiz = [
    {q:'¿Qué significa RAG?',opts:['Una técnica para entrenar modelos desde cero.','Recuperar información externa para apoyar la generación de respuestas.','Un formato especial para guardar archivos PDF.'],right:1,why:'RAG combina recuperación de datos relevantes con generación de respuestas apoyada en esos datos.'},
    {q:'¿Cuál es el riesgo de dividir siempre cada 100 caracteres?',opts:['Puede cortar condiciones, preguntas y respuestas.','Todos los chunks se vuelven embeddings automáticamente.','El modelo siempre responde más rápido y con mayor precisión.'],right:0,why:'Una división mecánica ignora significado y relaciones entre partes del documento.'},
    {q:'En la configuración vista de LangChain, ¿qué prioriza el splitter recursivo?',opts:['Romper primero las palabras más largas.','Elegir separadores jerárquicos, como párrafos y saltos de línea.','Calcular automáticamente embeddings con una API.'],right:1,why:'El splitter recursivo prueba una lista de separadores y desciende a niveles más finos cuando el texto sigue excediendo el tamaño.'},
    {q:'¿Para qué sirve el chunk_overlap?',opts:['Borrar automáticamente encabezados repetidos.','Aumentar el tamaño del PDF original.','Compartir parte del contenido entre fragmentos para conservar contexto.'],right:2,why:'El solapamiento reduce pérdidas en los límites, pero demasiado overlap también genera redundancia.'},
    {q:'¿Cómo puede detectar cortes el chunking semántico?',opts:['Midiendo cambios de similitud entre representaciones de oraciones cercanas.','Contando solo los caracteres de cada palabra.','Leyendo siempre un documento entero con un LLM.'],right:0,why:'Los embeddings permiten estimar similitud temática; cambios pronunciados pueden servir como fronteras.'},
    {q:'En Parent-Document Retrieval, ¿qué se indexa para buscar y qué se recupera?',opts:['Se indexan padres largos y solo se devuelve una palabra.','Se buscan hijos pequeños y se recupera el padre asociado.','Se elimina el padre y no se conserva ningún contexto.'],right:1,why:'Combina búsquedas precisas sobre hijos con respuestas basadas en bloques padre más completos.'},
    {q:'¿Qué harías al procesar un PDF con tablas y doble columna?',opts:['Usar siempre chunks de 50 caracteres.','Ignorar los metadatos y confiar en los embeddings.','Verificar extracción, preservar estructura y limpiar ruido antes de segmentar.'],right:2,why:'Si la extracción mezcló columnas o separó encabezados, cambiar el splitter no basta.'},
    {q:'¿Cómo elegís una estrategia para un proyecto real?',opts:['Comparando pruebas de recuperación, contexto, costo y los documentos reales.','Usando siempre el mayor overlap disponible.','Eligiendo la que produzca menos chunks, sin evaluar nada más.'],right:0,why:'No hay una estrategia universal: se evalúa contra preguntas representativas y requisitos del sistema.'}
  ];
  function exam(){
    const bestText=state.best>0?`Tu mejor marca guardada: ${state.best}/${quiz.length}.`:'Todavía no hay una marca guardada.';
    return `<div class="page lesson-page"><div class="lesson-head"><div class="lesson-topline"><span class="pill pink">CHECKPOINT FINAL</span><span class="lesson-count">08 PREGUNTAS · FEEDBACK INMEDIATO</span></div><h1>¿Ya podés pensar como <span class="glow-text">ingeniero RAG?</span></h1><p class="lead">No es un examen de memoria. Cada respuesta te obliga a elegir según el contexto, las limitaciones y la arquitectura de la solución.</p></div><div class="lesson-summary"><span class="summary-icon">✧</span><div>Respondé, comprobá la explicación y avanzá. <b>${bestText}</b> El progreso de la prueba se mantiene mientras navegás dentro de la sesión.</div></div><div class="quiz-wrap" id="quiz-area"></div><div class="panel note full"><span class="kicker">SIGUIENTE CAPÍTULO DE TU FORMACIÓN</span><h3>Embeddings y bases vectoriales</h3><p>Cuando entendés cómo preparar la información, el siguiente paso es aprender cómo convertirla en vectores y buscar por similitud. Ese es el tema de la Clase 2 del programa.</p><span class="source-chip">Páginas 30 a 32</span></div></div>`
  }
  const stories={
    meaning:{label:'El peligro del contexto roto',tag:'EL BUG INVISIBLE',title:['LA IA PUEDE','RESPONDER','MAL.'],accent:2,point:'No siempre falla el modelo. A veces el error está en cómo cortamos el documento.',detail:'Un chunk puede parecer relevante y estar incompleto.',caption:'¿Por qué un RAG puede dar respuestas incorrectas aunque encuentre el texto? Porque recuperar un fragmento no alcanza: hace falta conservar su contexto. Hoy aprendí sobre chunking y el impacto de la segmentación en sistemas RAG. #IA #RAG #Programación #LangChain'},
    recursive:{label:'Chunking recursivo',tag:'IDEAS QUE NO SE ROMPEN',title:['NO CORTES','PALABRAS.','CORTÁ IDEAS.'],accent:1,point:'Primero párrafos. Después líneas. Luego espacios. Caracteres, solo si hace falta.',detail:'La estructura del texto también es información.',caption:'Un buen text splitter intenta preservar la estructura: párrafos, líneas y palabras, antes de recurrir al corte por caracteres. Un detalle pequeño que puede cambiar la calidad de un sistema RAG. #IA #LangChain #RAG'},
    semantic:{label:'Chunking semántico',tag:'SIGNIFICADO > LONGITUD',title:['¿Y SI','CORTAMOS','POR SENTIDO?'],accent:2,point:'Los embeddings ayudan a detectar cuándo cambia el tema entre oraciones.',detail:'Menos corte mecánico. Más coherencia temática.',caption:'El chunking semántico usa representaciones vectoriales para detectar cambios de tema. No significa que una IA “comprenda perfecto”, sino que podemos medir similitudes para construir fragmentos más coherentes. #IA #Embeddings #RAG'},
    parent:{label:'Recuperación padre-hijo',tag:'PEQUEÑO PARA BUSCAR',title:['BUSCÁ','PEQUEÑO.','LEÉ GRANDE.'],accent:0,point:'Encontramos la pista en un chunk hijo. Recuperamos el bloque padre para responder con contexto.',detail:'Precisión para encontrar. Contexto para responder.',caption:'Parent-Document Retrieval combina dos ventajas: indexar fragmentos pequeños para encontrar detalles y recuperar bloques más amplios para no perder el contexto. #RAG #LangChain #AIEngineering'},
    cleanup:{label:'El problema de los PDFs',tag:'ANTES DEL SPLITTER',title:['LOS DATOS','SUCIOS','ROMPEN RAG.'],accent:1,point:'Tablas mezcladas, columnas fuera de orden y encabezados repetidos pueden arruinar la recuperación.',detail:'Primero extraé y limpiá. Después segmentá.',caption:'Un buen sistema RAG empieza antes del modelo y la base vectorial: empieza en el documento. Tablas, columnas, metadatos y limpieza son parte de la arquitectura. #RAG #DataEngineering #IA'}
  };
  function studio(){return `<div class="page lesson-page"><div class="lesson-head"><div class="lesson-topline"><span class="pill pink">CREATOR / MODE</span><span class="lesson-count">FORMATO 9:16 · 1080 × 1920</span></div><h1>Compartí lo que <span class="glow-text">aprendiste.</span></h1><p class="lead">Tu mini estudio para traducir conceptos de ingeniería en historias visuales que cualquier persona pueda entender. Elegí un tema y generá una imagen vertical lista para subir manualmente a Instagram.</p></div><div class="story-grid"><div class="story-config"><div class="panel"><div class="kicker">01 · ELEGÍ EL MENSAJE</div><h3>¿Qué querés contar hoy?</h3><label class="field-label" for="story-select">Concepto a compartir</label><select class="story-select" id="story-select">${Object.entries(stories).map(([id,v])=>`<option value="${id}" ${state.story===id?'selected':''}>${esc(v.label)}</option>`).join('')}</select><div class="divider"></div><div class="kicker">02 · EXPORTÁ</div><p>La imagen se dibuja localmente en tu navegador. No subimos tus datos ni usamos una API externa.</p><div class="story-actionrow"><button class="button button-pink" id="export-story">↓ Descargar PNG</button><button class="button button-outline" id="copy-caption">⧉ Copiar texto</button></div></div><div class="story-note"><b>Tip para Instagram:</b> subí la imagen como historia y acompañala con una encuesta: “¿Sabías que cortar mal un texto puede cambiar la respuesta de una IA?”. Para un reel, grabá la pantalla mientras movés los controles del laboratorio.</div><div class="panel"><span class="kicker">COPY SUGERIDO</span><p id="caption-preview" class="story-tip"></p></div></div><div><div class="story-preview" id="story-preview" role="img" aria-label="Vista previa de la historia de Instagram"></div><p style="text-align:center;color:var(--soft);font-size:11px;margin-top:14px">Vista previa aproximada. El botón exporta la versión en alta resolución.</p></div></div><div class="panel note full"><h3>¿Lo querés publicar como carrusel?</h3><p>Un carrusel sencillo puede seguir esta secuencia: <b>problema → ejemplo roto → explicación → solución → invitación a probar</b>. Compartí el link de este laboratorio en la bio o en una publicación para que otras personas también experimenten.</p></div></div>`}
  function render(){
    switch(state.current){case 'overview':main.innerHTML=overview();break;case 'intro':main.innerHTML=intro();break;case 'blind':main.innerHTML=blind();renderFixed();break;case 'recursive':main.innerHTML=recursive();renderRecursive();break;case 'semantic':main.innerHTML=semantic();renderSemantic();break;case 'parent':main.innerHTML=parent();renderParent();break;case 'real':main.innerHTML=real();renderClean('raw');break;case 'choose':main.innerHTML=choose();renderScenario();break;case 'exam':main.innerHTML=exam();renderQuiz();break;case 'studio':main.innerHTML=studio();renderStoryPreview();break;default:main.innerHTML=overview()}
  }
  function chunksToHTML(chunks){return chunks.map((s,i)=>`<div class="chunk"><small><span>CHUNK ${String(i+1).padStart(2,'0')}</span><span>${s.length} caracteres</span></small>${esc(s)||'<span class="text-muted">(vacío)</span>'}</div>`).join('')||'<div class="chunk">Ingresá algún texto para empezar.</div>'}
  function renderFixed(){if(state.current!=='blind')return;document.getElementById('fixed-out').textContent=`${state.fixedSize} caracteres`;const text=state.text;let chunks=[];for(let i=0;i<text.length;i+=state.fixedSize)chunks.push(text.slice(i,i+state.fixedSize));document.getElementById('fixed-result').innerHTML=chunksToHTML(chunks);document.getElementById('fixed-meta').innerHTML=`<span>LONGITUD: <strong>${text.length}</strong></span><span>CHUNKS: <strong>${chunks.length}</strong></span><span>OVERLAP: <strong>0</strong></span>`}
  // Simulador conceptual: descompone por niveles, agrupa y transporta solapamiento.
  // Mantiene el texto original en orden. No intenta replicar exactamente LangChain.
  function recursiveDemo(text,size,overlap){
    if(!text)return [];
    const separators=['\n\n','\n',' ',''];
    function splitBig(s,level){
      if(s.length<=size)return [s];
      if(level>=separators.length-1){const out=[];for(let i=0;i<s.length;i+=size)out.push(s.slice(i,i+size));return out}
      const sep=separators[level];const parts=s.split(sep);
      if(parts.length===1)return splitBig(s,level+1);
      const pieces=[];parts.forEach((p,i)=>{
        const piece=(i>0?sep:'')+p;
        if(!piece)return;
        pieces.push(...(piece.length>size?splitBig(piece,level+1):[piece]));
      });
      return pieces;
    }
    const pieces=splitBig(text,0);const result=[];let cur='';
    for(const piece of pieces){
      if(cur.length+piece.length<=size){cur+=piece;continue}
      if(cur){result.push(cur);const keep=Math.min(overlap,cur.length,size-piece.length);cur=keep>0?cur.slice(-keep):''}
      cur+=piece;
    }
    if(cur)result.push(cur);
    return result;
  }
  function renderRecursive(){if(state.current!=='recursive')return;const effectiveOverlap=Math.min(state.recOverlap,Math.max(0,state.recSize-10));document.getElementById('recursive-out').textContent=`${state.recSize} caracteres`;document.getElementById('overlap-out').textContent=`${effectiveOverlap} caracteres`;const chunks=recursiveDemo(state.recText,state.recSize,effectiveOverlap);document.getElementById('recursive-result').innerHTML=chunksToHTML(chunks);document.getElementById('recursive-meta').innerHTML=`<span>CHUNKS: <strong>${chunks.length}</strong></span><span>TEXTO: <strong>${state.recText.length} caracteres</strong></span>`}
  function semanticGroups(){const thresh=state.semThreshold/100, groups=[[semanticSentences[0]]];for(let i=1;i<semanticSentences.length;i++){if(demoSimilarities[i-1]<thresh)groups.push([]);groups[groups.length-1].push(semanticSentences[i])}return groups}
  function renderSemantic(){if(state.current!=='semantic')return;const threshold=state.semThreshold/100;document.getElementById('semantic-out').textContent=threshold.toFixed(2);let list='';semanticSentences.forEach((s,i)=>{list+=`<div class="similarity-item">${esc(s)}</div>`;if(i<demoSimilarities.length){const sim=demoSimilarities[i],cut=sim<threshold;list+=`<div class="similarity-indicator"><span>${cut?'✂ CORTE':'↔ UNIÓN'}</span><div class="similarity-bar"><span style="width:${sim*100}%;${cut?'background:var(--pink)':''}"></span></div><strong style="color:${cut?'var(--pink)':'var(--cyan)'}">${sim.toFixed(2)}</strong></div>`}});document.getElementById('similarity-list').innerHTML=list;const groups=semanticGroups();document.getElementById('semantic-groups').innerHTML=groups.map((group,i)=>`<div class="semantic-group"><b>GRUPO ${String(i+1).padStart(2,'0')} · ${group.length} oraciones</b>${group.map(s=>`<p>${esc(s)}</p>`).join('')}</div>`).join('');document.getElementById('semantic-meta').innerHTML=`<span>GRUPOS: <strong>${groups.length}</strong></span><span>SIMILITUDES: <strong>ilustrativas</strong></span>`}
  function renderParent(){if(state.current!=='parent')return;const d=parentDocs[state.retrieval];document.getElementById('retrieval-result').innerHTML=`<div class="retrieval-child"><span class="pill pink">01 · HIJO ENCONTRADO</span><h4 style="margin-top:15px">“${esc(d.question)}”</h4><p>${esc(d.short)}</p></div><div class="retrieval-parent"><span class="pill">02 · PADRE RECUPERADO</span><h4 style="margin-top:15px">${esc(d.label)}</h4><p>${esc(d.full)}</p></div>`;document.getElementById('retrieval-reason').innerHTML=`<b>¿Qué ganamos?</b> ${esc(d.reason)}`;document.querySelectorAll('[data-retrieval]').forEach(b=>b.classList.toggle('selected',b.dataset.retrieval===state.retrieval))}
  function renderClean(mode){if(state.current!=='real')return;const dirty=`FARMACIA CENTRAL        REPORTE 2026     pág. 12\nPRODUCTO       STOCK     PVP   OBSERVACIONES\nRexona        12\nColgate                $ 4.500\n7               $ 3.800\nIMPORTANTE: NO REPO\nNER SIN REVISAR VMD\nREPORTE 2026 / pág. 12`;const clean=`SECCIÓN: CONTROL DE INVENTARIO\n\nTABLA PRESERVADA\nProducto | Stock | PVP\nRexona   | 12    | $4.500\nColgate  | 7     | $3.800\n\nINDICACIÓN\nNo reponer sin revisar VMD.\n\nMETADATOS\nsource: reporte_inventario.pdf\npage_number: 12\nsection_title: Control de inventario`;
    document.getElementById('clean-output').innerHTML=`<span class="pill ${mode==='clean'?'green':'pink'}">${mode==='clean'?'✓ TEXTO ESTRUCTURADO':'! EXTRACCIÓN DESORDENADA'}</span><pre style="white-space:pre-wrap;word-break:break-word;padding:15px 0 0;font-size:12px">${esc(mode==='clean'?clean:dirty)}</pre><p style="margin-top:8px;font-size:11px">${mode==='clean'?'Los valores se reordenaron para esta demostración y se agregaron metadatos. En un caso real tendrías que verificar las asociaciones entre celdas.':'¿Qué stock pertenece a Colgate? ¿Cuál es el PVP de Rexona? Sin estructura es fácil asociar mal los valores.'}</p>`;
    document.getElementById('clean-raw').classList.toggle('button-outline',mode==='clean');document.getElementById('clean-good').classList.toggle('button-outline',mode==='raw')
  }
  function renderScenario(){if(state.current!=='choose')return;const s=scenarios[state.scenario];document.getElementById('scenario-result').innerHTML=`<span class="kicker">SUGERENCIA INICIAL PARA ESTE ESCENARIO</span><h3 style="font-size:25px;color:var(--cyan)">${esc(s.method)}</h3><p>${esc(s.why)}</p><div class="divider"></div><p><b class="text-pink">⚠ Antes de implementar:</b> ${esc(s.warning)}</p>`;document.querySelectorAll('[data-scenario]').forEach(b=>b.classList.toggle('selected',b.dataset.scenario===state.scenario))}
  function renderQuiz(){if(state.current!=='exam')return;const target=document.getElementById('quiz-area');if(!target)return;if(state.quizIndex>=quiz.length){let score=state.quizScore;const percent=Math.round(100*score/quiz.length);target.innerHTML=`<div class="quiz-card score-summary"><span class="pill green">RECORRIDO FINALIZADO</span><h2 style="font-size:30px;margin:20px 0">${score===quiz.length?'Dominás los fundamentos.':score>=5?'Muy buen comienzo.':'Cada error es una pista.'}</h2><div class="score-number">${percent}%</div><p>Respondiste correctamente <b>${score} de ${quiz.length}</b> preguntas. ${score===quiz.length?'Ahora practicá con documentos reales.':'Repasá los capítulos donde dudaste y volvé a intentarlo.'}</p><div class="story-actionrow" style="justify-content:center"><button class="button" data-reset-exam>↺ Intentar otra vez</button><button class="button button-outline" data-go="studio">Crear historia IG ↗</button></div></div>`;return}
    const q=quiz[state.quizIndex];let options=q.opts.map((label,i)=>{let status='';if(state.quizRevealed){if(i===q.right)status='right';else if(i===state.quizPick)status='wrong'}else if(state.quizPick===i)status='selected';return `<button class="quiz-option ${status}" data-pick="${i}" ${state.quizRevealed?'disabled':''}><span class="answer-letter">${'ABC'[i]}</span><span>${esc(label)}</span></button>`}).join('');target.innerHTML=`<div class="quiz-progress" aria-label="Pregunta ${state.quizIndex+1} de ${quiz.length}">${quiz.map((_,i)=>`<span class="${i<state.quizIndex?'done':i===state.quizIndex?'current':''}"></span>`).join('')}</div><div class="quiz-card"><div class="lesson-topline"><span class="pill pink">PREGUNTA ${String(state.quizIndex+1).padStart(2,'0')} / ${quiz.length}</span><span class="lesson-count">ACIERTOS: ${state.quizScore}</span></div><h2 class="quiz-question">${esc(q.q)}</h2><div class="quiz-options">${options}</div>${state.quizRevealed?`<div class="quiz-feedback ${state.quizPick===q.right?'good':'bad'}"><b>${state.quizPick===q.right?'✓ Correcto':'✕ Esta vez no'}</b><div>${esc(q.why)}</div></div>`:''}<div class="quiz-actions"><span class="text-muted" style="font-size:11px">${state.quizRevealed?'Leé la explicación antes de seguir.':'Elegí una opción para continuar.'}</span>${state.quizRevealed?`<button class="button" data-next-question>${state.quizIndex===quiz.length-1?'Ver resultado →':'Siguiente →'}</button>`:`<button class="button" data-check-answer ${state.quizPick===null?'disabled':''}>Comprobar →</button>`}</div></div>`}
  function storyTitleHTML(title,accent){return title.map((line,i)=>`<div ${i===accent?'style="color:var(--cyan)"':''}>${esc(line)}</div>`).join('')}
  function renderStoryPreview(){if(state.current!=='studio')return;const s=stories[state.story];document.getElementById('story-preview').innerHTML=`<div class="story-content"><div class="story-logo">NEXO <b>/</b> RAG LAB</div><div class="story-center"><span class="story-sticker">${esc(s.tag)}</span><div class="story-title">${storyTitleHTML(s.title,s.accent)}</div><div class="story-point">${esc(s.point)}</div></div><div class="story-footer"><span>MÓDULO 01 · CLASE 01</span><span>APRENDER HACIENDO ↗</span></div></div>`;document.getElementById('caption-preview').textContent=s.caption}
  // Canvas story export, 1080×1920, PNG, funciona sin dependencias ni conexiones.
  function drawStory(){const s=stories[state.story];const c=document.createElement('canvas');c.width=1080;c.height=1920;const x=c.getContext('2d');if(!x){toast('No se pudo iniciar Canvas');return}
    const w=c.width,h=c.height;const gradient=x.createLinearGradient(0,0,w,h);gradient.addColorStop(0,'#080e20');gradient.addColorStop(.55,'#111638');gradient.addColorStop(1,'#210f30');x.fillStyle=gradient;x.fillRect(0,0,w,h);
    const glow=(cx,cy,r,col)=>{const g=x.createRadialGradient(cx,cy,10,cx,cy,r);g.addColorStop(0,col);g.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=g;x.fillRect(cx-r,cy-r,r*2,r*2)};
    glow(900,360,770,'rgba(53,170,205,.18)');glow(110,1390,700,'rgba(211,67,171,.19)');glow(530,800,450,'rgba(109,74,210,.09)');
    x.save();x.translate(560,825);x.rotate(-.25);for(const [rx,ry,stroke] of [[390,310,'rgba(101,234,243,.22)'],[490,420,'rgba(251,119,206,.18)'],[600,520,'rgba(101,234,243,.09)']]){x.beginPath();x.ellipse(0,0,rx,ry,0,0,Math.PI*2);x.strokeStyle=stroke;x.lineWidth=2;x.stroke()}x.restore();
    let seed=17;const rand=()=>{seed=(seed*9301+49297)%233280;return seed/233280};for(let i=0;i<220;i++){let px=rand()*w,py=rand()*h;x.fillStyle=`rgba(192,224,255,${.12+rand()*.45})`;x.beginPath();x.arc(px,py,rand()*2.2+.4,0,Math.PI*2);x.fill()}
    x.fillStyle='#f8fbff';x.font='bold 37px Arial';x.fillText('NEXO',76,125);x.fillStyle='#65eaf3';x.fillText(' / ',205,125);x.fillStyle='#f8fbff';x.fillText('RAG LAB',258,125);
    x.strokeStyle='rgba(169,195,239,.3)';x.beginPath();x.moveTo(76,171);x.lineTo(1003,171);x.stroke();
    x.fillStyle='rgba(101,234,243,.1)';x.fillRect(76,605,490,68);x.strokeStyle='rgba(101,234,243,.55)';x.strokeRect(76,605,490,68);x.fillStyle='#65eaf3';x.font='bold 26px Consolas, monospace';x.fillText(s.tag,95,650);
    const titleY=790;for(let i=0;i<s.title.length;i++){x.fillStyle=i===s.accent?'#65eaf3':'#f7f8ff';x.font='900 104px Arial';x.fillText(s.title[i],72,titleY+i*129,945)}
    let cy=1265;x.fillStyle='#fb77ce';x.fillRect(79,cy-52,6,290);x.fillStyle='#e4ecff';x.font='38px Arial';cy=wrapText(x,s.point,115,cy,830,53);cy+=62;x.fillStyle='#a7b9d4';x.font='30px Arial';wrapText(x,s.detail,114,cy,830,43);
    x.strokeStyle='rgba(240,243,255,.3)';x.beginPath();x.moveTo(76,1760);x.lineTo(1004,1760);x.stroke();x.fillStyle='#a8b9d2';x.font='bold 25px Consolas, monospace';x.fillText('MÓDULO 01  ·  CLASE 01',76,1820);x.fillText('APRENDER HACIENDO ↗',690,1820);
    const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download=`NEXO_RAG_Lab_${state.story}_Historia_IG.png`;document.body.appendChild(a);a.click();a.remove();toast('✓ Historia 1080 × 1920 exportada como PNG.')
  }
  function wrapText(ctx,text,x,y,maxWidth,lineHeight){const words=text.split(' ');let line='';for(const word of words){const attempt=line?line+' '+word:word;if(ctx.measureText(attempt).width>maxWidth&&line){ctx.fillText(line,x,y);y+=lineHeight;line=word}else line=attempt}if(line)ctx.fillText(line,x,y);return y+lineHeight}
  async function copyText(text){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);toast('✓ Copiado al portapapeles.');return}}catch{}const el=document.createElement('textarea');el.value=text;el.style.position='fixed';el.style.opacity='0';document.body.appendChild(el);el.select();try{const ok=document.execCommand('copy');toast(ok?'✓ Copiado al portapapeles.':'Seleccioná y copiá el texto manualmente.')}catch{toast('No se pudo copiar automáticamente.')}el.remove()}
  document.addEventListener('click',e=>{
    const btn=e.target.closest('button');if(!btn)return;
    if(btn.dataset.go){go(btn.dataset.go);return}
    if(btn.dataset.complete){complete(btn.dataset.complete);return}
    if(btn.dataset.copy){copyText(window.__nexoCode?.[btn.dataset.copy]||'');return}
    if(btn.dataset.retrieval){state.retrieval=btn.dataset.retrieval;renderParent();return}
    if(btn.dataset.clean){renderClean(btn.dataset.clean);return}
    if(btn.dataset.scenario){state.scenario=btn.dataset.scenario;renderScenario();return}
    if(btn.hasAttribute('data-pick')&&!state.quizRevealed){state.quizPick=Number(btn.dataset.pick);renderQuiz();return}
    if(btn.hasAttribute('data-check-answer')&&state.quizPick!==null){state.quizRevealed=true;if(state.quizPick===quiz[state.quizIndex].right)state.quizScore++;renderQuiz();return}
    if(btn.hasAttribute('data-next-question')){state.quizIndex++;state.quizPick=null;state.quizRevealed=false;if(state.quizIndex===quiz.length){state.best=Math.max(state.best,state.quizScore);complete('exam')}renderQuiz();return}
    if(btn.hasAttribute('data-reset-exam')){state.quizIndex=0;state.quizPick=null;state.quizScore=0;state.quizRevealed=false;renderQuiz();return}
    if(btn.id==='export-story'){drawStory();return}
    if(btn.id==='copy-caption'){copyText(stories[state.story].caption);return}
  });
  document.addEventListener('input',e=>{
    const el=e.target;if(el.id==='fixed-size'){state.fixedSize=Number(el.value);renderFixed()}
    if(el.id==='fixed-text'){state.text=el.value;renderFixed()}
    if(el.id==='recursive-size'){state.recSize=Number(el.value);renderRecursive()}
    if(el.id==='overlap-size'){state.recOverlap=Number(el.value);renderRecursive()}
    if(el.id==='recursive-text'){state.recText=el.value;renderRecursive()}
    if(el.id==='semantic-threshold'){state.semThreshold=Number(el.value);renderSemantic()}
  });
  document.addEventListener('change',e=>{if(e.target.id==='story-select'){state.story=e.target.value;renderStoryPreview()}});
  // Fondo animado sutil. Se desactiva bajo preferencias de movimiento reducido.
  function initAmbient(){const c=document.getElementById('ambient'),ctx=c.getContext('2d');if(!ctx)return;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;let w=0,h=0,dpr=1,pts=[];function size(){dpr=Math.min(window.devicePixelRatio||1,2);w=window.innerWidth;h=window.innerHeight;c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);const n=Math.min(65,Math.ceil(w*h/25000));pts=Array.from({length:n},()=>({x:Math.random()*w,y:Math.random()*h,r:.5+Math.random()*1.3,s:.05+Math.random()*.16}))}size();window.addEventListener('resize',size);function draw(){ctx.clearRect(0,0,w,h);for(let i=0;i<pts.length;i++){const p=pts[i];ctx.fillStyle='rgba(139,181,235,.32)';ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();if(!reduced){p.y+=p.s;if(p.y>h)p.y=0}}for(let i=0;i<pts.length;i++){for(let j=i+1;j<pts.length;j++){const a=pts[i],b=pts[j],dist=Math.hypot(a.x-b.x,a.y-b.y);if(dist<125){ctx.strokeStyle=`rgba(63,108,170,${(1-dist/125)*.12})`;ctx.lineWidth=.5;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}}if(!reduced&&document.visibilityState==='visible')requestAnimationFrame(draw)}draw();document.addEventListener('visibilitychange',()=>{if(!reduced&&document.visibilityState==='visible')requestAnimationFrame(draw)})}
  refreshNav();render();initAmbient();
})();
